<?php
namespace Tests\Feature;
use App\Models\ShopUser;
use App\Support\BusinessSettings;
use Illuminate\Foundation\Testing\DatabaseTransactions;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Tests\TestCase;

class BusinessTest extends TestCase
{
 use DatabaseTransactions;
 private function owner($role='super_admin') { $id=DB::table('users')->insertGetId(['name'=>'QA Owner','email'=>Str::uuid().'@example.test','password_hash'=>bcrypt('A strong test password!'),'role'=>$role]);$u=ShopUser::find($id);$this->withSession(['auth_version'=>$u->auth_version]);return $this->actingAs($u); }
 private function product(){ $id=DB::table('products')->insertGetId(['name'=>'QA Business Saree','category'=>DB::table('categories')->value('name'),'brand'=>DB::table('brands')->value('name'),'price'=>1000,'stock'=>3,'image'=>'/images/gold.jpg','sku'=>'QA-'.Str::uuid(),'cost_price'=>400,'additional_cost'=>0,'stitching_cost'=>500,'stitching_stock_mode'=>'shared']);$a=DB::table('product_variants')->insertGetId(['product_id'=>$id,'type'=>'Unstitched','regular_price'=>1000,'stock'=>3,'enabled'=>1]);$b=DB::table('product_variants')->insertGetId(['product_id'=>$id,'type'=>'Stitched','regular_price'=>1,'stock'=>0,'enabled'=>0]);return [$id,$a,$b]; }
 private function body($id,$variant,$qty=1){return ['name'=>'QA Guest','email'=>'qa-business@example.test','phone'=>'03001234567','address'=>'QA address','city'=>'Lahore','postal_code'=>'54000','payment_method'=>'cod','checkout_token'=>(string)Str::uuid(),'items'=>[['id'=>$id,'variant_id'=>$variant,'quantity'=>$qty]]];}
 private function order($p,$email,$city,$paid,$cost=400,$status='Delivered'){ $id=DB::table('orders')->insertGetId(['reference'=>'QA-'.Str::uuid(),'name'=>'QA Buyer','email'=>$email,'phone'=>'03001234567','address'=>'QA only','city'=>$city,'payment_method'=>'cod','total'=>1000,'shipping'=>0,'status'=>$status,'payment_status'=>$paid===null?'Unrecorded':'Paid','amount_paid'=>$paid,'created_at'=>'2026-10-15 12:00:00']);DB::table('order_items')->insert(['order_id'=>$id,'product_id'=>$p,'name'=>'QA Business Saree','variant'=>'Unstitched','price'=>1000,'quantity'=>1,'unit_cost'=>$cost]);return$id; }
 public function test_shipping_settings_boundaries_and_permissions(){ $this->assertEquals(350,BusinessSettings::shipping(9999));$this->assertEquals(350,BusinessSettings::shipping(10000));$this->assertEquals(0,BusinessSettings::shipping(10000.01));$this->getJson('/api/settings')->assertJsonPath('business.default_stitching_charge',5000);$this->owner('staff')->putJson('/api/admin/business-settings',['standard_delivery_charge'=>1])->assertForbidden();$this->owner()->putJson('/api/admin/business-settings',['standard_delivery_charge'=>400,'free_delivery_threshold'=>12000,'default_stitching_charge'=>6000,'return_address'=>'QA Updated Address'])->assertOk();$this->assertEquals(400,BusinessSettings::shipping(12000));$this->assertEquals(0,BusinessSettings::shipping(12001));$this->getJson('/api/settings')->assertJsonPath('business.return_address','QA Updated Address'); }
 public function test_stitching_formula_shared_stock_charge_snapshots_and_verified_reference(){[$id,$a,$b]=$this->product();$catalog=collect($this->getJson('/api/catalog')->assertOk()->json('products'))->firstWhere('id',$id);$this->assertEquals(3,$catalog['stock']);$this->assertEquals(6000,$catalog['variants'][1]['price']);$this->assertTrue((bool)$catalog['variants'][1]['enabled']);$body=$this->body($id,$b,2);$r=$this->postJson('/api/orders',$body)->assertCreated()->assertJsonPath('total',12000);$ref=$r->json('reference');$this->assertMatchesRegularExpression('/^RM-SR-\d{8}-\d{6,}$/',$ref);$this->assertDatabaseHas('order_items',['variant_id'=>$b,'stock_variant_id'=>$a,'stitching_charge'=>5000,'price'=>6000,'quantity'=>2,'unit_cost'=>900]);$this->assertDatabaseHas('product_variants',['id'=>$a,'stock'=>1]);$this->postJson('/api/track',['reference'=>$ref])->assertUnprocessable();$this->postJson('/api/track',['reference'=>$ref,'email'=>'wrong@example.test'])->assertNotFound();$this->postJson('/api/track',['reference'=>$ref,'email'=>$body['email']])->assertOk()->assertJsonPath('order.payment_status','Pending')->assertJsonCount(1,'order.status_history');$this->postJson('/api/orders',[...$this->body($id,$a),'items'=>[['id'=>$id,'variant_id'=>$a,'quantity'=>1],['id'=>$id,'variant_id'=>$b,'quantity'=>1]]])->assertStatus(409);$next=$this->postJson('/api/orders',$this->body($id,$a))->assertCreated();$this->assertEquals((int)substr($ref,-6)+1,(int)substr($next->json('reference'),-6));$this->assertDatabaseHas('product_variants',['id'=>$a,'stock'=>0]); }
 public function test_per_product_override_and_no_cost_leak(){[$id,$a,$b]=$this->product();DB::table('products')->where('id',$id)->update(['stitching_charge'=>700]);$p=collect($this->getJson('/api/catalog')->json('products'))->firstWhere('id',$id);$this->assertEquals(1700,$p['variants'][1]['price']);$this->assertArrayNotHasKey('cost_price',$p);$this->owner('product_manager');$p=collect($this->getJson('/api/admin/data')->assertOk()->json('products'))->firstWhere('id',$id);$this->assertArrayNotHasKey('cost_price',$p);$this->getJson('/api/admin/analytics')->assertForbidden();$this->owner('admin')->getJson('/api/admin/analytics')->assertForbidden();DB::table('products')->where('id',$id)->update(['stitching_enabled'=>false]);$p=collect($this->getJson('/api/catalog')->json('products'))->firstWhere('id',$id);$this->assertFalse((bool)$p['variants'][1]['enabled']); }
 public function test_database_financial_analytics_filters_and_missing_costs(){[$id]=$this->product();$this->order($id,'qa-one@example.test','Karachi',1000);$this->order($id,'qa-two@example.test','Lahore',null,null,'Pending');$this->owner();$d=$this->getJson('/api/admin/analytics?from=2026-10-01&to=2026-10-31&city=Karachi')->assertOk();$d->assertJsonPath('kpis.revenue',1000)->assertJsonPath('kpis.orders',1)->assertJsonPath('profitability.gross_profit',600)->assertJsonPath('profitability.margin',60)->assertJsonPath('profitability.by_product.0.profit',600);$this->assertCount(1,$d->json('cities'));$id2=$this->order($id,'qa-three@example.test','Karachi',1000,null);$this->getJson('/api/admin/analytics?city=Karachi')->assertOk()->assertJsonPath('kpis.revenue',2000)->assertJsonPath('profitability.available',false)->assertJsonPath('profitability.cost',null);DB::table('orders')->where('id',$id2)->update(['refund_amount'=>100,'payment_status'=>'Partially Refunded']);$this->getJson('/api/admin/analytics?city=Karachi')->assertOk()->assertJsonPath('kpis.revenue',1900)->assertJsonPath('profitability.gross_profit',null); }
 public function test_customer_search_profiles_duplicates_and_record_scoping(){[$id]=$this->product();$this->order($id,'qa-a@example.test','Karachi',1000);$this->order($id,'qa-a@example.test','Karachi',null,null,'Pending');$this->order($id,'qa-b@example.test','Lahore',null,null,'Pending');$this->owner('order_manager');$d=$this->getJson('/api/admin/customers?q=03001234567&city=Karachi')->assertOk()->assertJsonPath('total',1)->assertJsonPath('customers.0.order_count',2);$this->getJson('/api/admin/customers?q=QA%20Buyer')->assertOk()->assertJsonPath('total',2)->assertJsonPath('customers.0.possible_duplicate',true);$this->putJson('/api/admin/customers',['email'=>'qa-a@example.test','category'=>'VIP','status'=>'Active','notes'=>'QA profile'])->assertOk();$this->getJson('/api/admin/customers?customer_category=VIP')->assertOk()->assertJsonPath('total',1);$this->getJson('/api/admin/customers?email=qa-a%40example.test')->assertOk()->assertJsonCount(2,'orders');$this->owner('product_manager')->getJson('/api/admin/customers')->assertForbidden(); }
 public function test_shipment_records_validate_actual_money_and_status_history(){[$id,$a]=$this->product();$r=$this->postJson('/api/orders',$this->body($id,$a))->assertCreated();$o=DB::table('orders')->where('reference',$r->json('reference'))->first();$this->owner('order_manager');$base=['id'=>$o->id,'payment_status'=>'Paid','amount_paid'=>$o->total,'refund_amount'=>0,'courier_name'=>'QA Courier','courier_tracking_number'=>'QA-123','courier_tracking_url'=>'https://example.test/track/QA-123','estimated_delivery_date'=>'2026-11-10'];$this->getJson('/api/admin/order-search?q='.urlencode($o->reference))->assertOk()->assertJsonPath('total',1)->assertJsonMissingPath('orders.0.checkout_token');$this->getJson('/api/admin/order-items?id='.$o->id)->assertOk()->assertJsonMissingPath('items.0.unit_cost');$this->putJson('/api/admin/shipment',[...$base,'amount_paid'=>1])->assertUnprocessable();$this->putJson('/api/admin/shipment',$base)->assertOk();$this->postJson('/api/track',['reference'=>$o->reference,'email'=>$o->email])->assertOk()->assertJsonPath('order.courier_name','QA Courier')->assertJsonPath('order.payment_status','Paid');$this->putJson('/api/admin/orders',['id'=>$o->id,'status'=>'Confirmed'])->assertOk();$this->postJson('/api/track',['reference'=>$o->reference,'email'=>$o->email])->assertOk()->assertJsonCount(2,'order.status_history'); }
 public function test_taxonomy_rename_preserves_associations_and_seo_route(){[$id]=$this->product();$p=DB::table('products')->find($id);$category=DB::table('categories')->where('name',$p->category)->first();$this->owner('product_manager')->putJson('/api/admin/categories',['id'=>$category->id,'name'=>'QA Renamed Category'])->assertOk();$this->assertDatabaseHas('products',['id'=>$id,'category'=>'QA Renamed Category']);DB::table('products')->where('id',$id)->update(['seo_title'=>'QA Saree SEO','seo_description'=>'QA accurate description']);$this->get('/products/'.$id)->assertOk()->assertSee('QA Saree SEO')->assertSee('QA accurate description');$this->get('/track')->assertOk(); }
}
